player_move:
void WdmPlayerShip::Move(float dltTime)
{
    CONTROL_STATE cs;
    // Forward
    core.Controls->GetControlState("WMapShipSailUp", cs);
    if (cs.state == CST_ACTIVE || cs.state == CST_ACTIVATED)
        goForward = true;
    core.Controls->GetControlState("WMapShipSailUp1", cs);
    if (cs.state == CST_ACTIVE || cs.state == CST_ACTIVATED)
        goForward = true;
    if (goForward)
        speed += WDM_SHIP_INER_ST * WDM_SHIP_MAX_SPEED * dltTime * 0.5f;
    // Back
    auto isBack = false;
    core.Controls->GetControlState("WMapShipSailDown", cs);
    if (cs.state == CST_ACTIVE)
        isBack = true;
    core.Controls->GetControlState("WMapShipSailDown1", cs);
    if (cs.state == CST_ACTIVE)
        isBack = true;
    if (isBack)
    {
        goForward = false;
        speed -= WDM_SHIP_INER_ST * WDM_SHIP_MAX_SPEED * dltTime * 0.5f;
        if (speed < 0.0f)
        {
            speed = 0.0f;
        }
    }
    core.Controls->GetControlState("WMapShipSailDown", cs);
    // Turns
    auto isTurn = false;
    core.Controls->GetControlState("WMapShipTurnLeft", cs);
    if (cs.state == CST_ACTIVE)
        isTurn = true;
    core.Controls->GetControlState("WMapShipTurnLeft1", cs);
    if (cs.state == CST_ACTIVE)
        isTurn = true;
    if (isTurn)
        turnspd -= WDM_SHIP_INER_ST * WDM_SHIP_TSPEED * dltTime;
    isTurn = false;
    core.Controls->GetControlState("WMapShipTurnRight", cs);
    if (cs.state == CST_ACTIVE)
        isTurn = true;
    core.Controls->GetControlState("WMapShipTurnRight1", cs);
    if (cs.state == CST_ACTIVE)
        isTurn = true;
    if (isTurn)
        turnspd += WDM_SHIP_INER_ST * WDM_SHIP_TSPEED * dltTime;
}

enemy_move:
void WdmEnemyShip::Move(float dltTime)
{
    // Calculating the turn response
    // Where to sail
    FindMoveForce();
    // The hidden ordinary fleet only integrates on accepted calendar pulses.
    // Keep route/lifecycle updates on zero-time frames without recomputing
    // transient avoidance forces that the next positive step replaces.
    if (dltTime != 0.f || !wdmObjects->wm->IsSeaTraffic() || !GetTrafficData())
    {
        FindIslandForce();
        FindShipsForce();
    }
    // The resulting
    dx = 1.0f * mx + 2.0f * ix + 1.2f * sx;
    dz = 1.0f * mz + 2.0f * iz + 1.2f * sz;
    const auto dl = dx * dx + dz * dz;
    // Our direction
    const auto vx = mtx.Vz().x;
    const auto vz = mtx.Vz().z;
    const auto vl = vx * vx + vz * vz;
    // The sine of the angle between this pair of vectors
    auto sn = vz * dx - vx * dz;
    if (dl * vl > 0.0f)
        sn /= sqrtf(dl * vl);
    // If the player is behind, then make a full turn
    const auto cs = vx * dx + vz * dz;
    if (cs < 0.0f)
    {
        if (fabsf(sn) < 0.05f)
            sn = (turnspd >= 0.0f ? 1.0f : -1.0f);
        else if (sn < 0.0f)
            sn = -1.0f;
        else
            sn = 1.0f;
    }
    // Turning reaction
    turnspd += 2.0f * WDM_SHIP_TSPEED * sn * dltTime;
    // Speed control
    if (cs >= 0.0f)
    {
        speed += kMaxSpeed * WDM_SHIP_INER_ST * WDM_SHIP_SPEED * dltTime;
    }
    else
    {
        const float minManeuverSpeed = 0.35f * WDM_SHIP_SPEED * kMaxSpeed;
        if (speed > minManeuverSpeed)
        {
            speed -= kMaxSpeed * WDM_SHIP_INER_ST * WDM_SHIP_SPEED * dltTime;
            if (speed < minManeuverSpeed)
                speed = minManeuverSpeed;
        }
        else if (speed < minManeuverSpeed)
        {
            speed += kMaxSpeed * WDM_SHIP_INER_ST * WDM_SHIP_SPEED * dltTime;
            if (speed > minManeuverSpeed)
                speed = minManeuverSpeed;
        }
    }
    speed *= slowingAlfa;
    turnspd *= slowingAlfa;
}
